draw:
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.4;
ctx.textAlign = "center";

function arrow(x0, y0, x1, y1, col) {
  ctx.strokeStyle = col;
  ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x1, y1); ctx.stroke();
  var a = Math.atan2(y1 - y0, x1 - x0);
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x1 - 7 * Math.cos(a - 0.4), y1 - 7 * Math.sin(a - 0.4));
  ctx.moveTo(x1, y1);
  ctx.lineTo(x1 - 7 * Math.cos(a + 0.4), y1 - 7 * Math.sin(a + 0.4));
  ctx.stroke();
}

ctx.strokeStyle = C.rule;
ctx.setLineDash([4, 4]);
ctx.beginPath(); ctx.moveTo(W * 0.5, 6); ctx.lineTo(W * 0.5, H - 6); ctx.stroke();
ctx.setLineDash([]);

ctx.fillStyle = C.ink;
ctx.fillText("STAGE 1: the bang  -  use momentum", W * 0.25, 18);
ctx.fillText("STAGE 2: the swing  -  use energy", W * 0.75, 18);

var pivx = W * 0.25, pivy = 34;
var Lr = H * 0.46;
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(pivx - 30, pivy); ctx.lineTo(pivx + 30, pivy); ctx.stroke();
ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.moveTo(pivx, pivy); ctx.lineTo(pivx, pivy + Lr); ctx.stroke();

var bw = 26;
ctx.fillStyle = C.figure;
ctx.fillRect(pivx - bw / 2, pivy + Lr, bw, bw);
ctx.fillStyle = C.paper;
ctx.fillText("M", pivx, pivy + Lr + 17);

ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(pivx - 60, pivy + Lr + bw / 2, 5, 0, Math.PI * 2); ctx.fill();
arrow(pivx - 54, pivy + Lr + bw / 2, pivx - 22, pivy + Lr + bw / 2, C.accent);
ctx.fillStyle = C.accent;
ctx.fillText("m, speed v", pivx - 60, pivy + Lr - 8);

ctx.fillStyle = C.ink;
ctx.fillText("m v = (m + M) V", W * 0.25, pivy + Lr + 48);
ctx.fillStyle = C.faint;
ctx.fillText("energy is NOT conserved here", W * 0.25, pivy + Lr + 66);

var pv2 = W * 0.75;
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(pv2 - 30, pivy); ctx.lineTo(pv2 + 30, pivy); ctx.stroke();
var ang = 0.62;
var ex = pv2 + Lr * Math.sin(ang), ey = pivy + Lr * Math.cos(ang);
ctx.strokeStyle = C.faint;
ctx.setLineDash([3, 3]);
ctx.beginPath(); ctx.moveTo(pv2, pivy); ctx.lineTo(pv2, pivy + Lr); ctx.stroke();
ctx.setLineDash([]);
ctx.strokeStyle = C.figure;
ctx.beginPath(); ctx.moveTo(pv2, pivy); ctx.lineTo(ex, ey); ctx.stroke();
ctx.fillStyle = C.figure;
ctx.fillRect(ex - bw / 2, ey, bw, bw);
ctx.fillStyle = C.paper;
ctx.fillText("m+M", ex, ey + 17);

ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 3]);
ctx.beginPath(); ctx.moveTo(pv2 - 40, pivy + Lr); ctx.lineTo(ex + 40, pivy + Lr); ctx.stroke();
ctx.beginPath(); ctx.moveTo(ex + 40, ey); ctx.lineTo(ex, ey); ctx.stroke();
ctx.setLineDash([]);
arrow(ex + 34, pivy + Lr, ex + 34, ey + 2, C.accent);
ctx.fillStyle = C.accent;
ctx.textAlign = "left";
ctx.fillText("h", ex + 40, (ey + pivy + Lr) / 2);

ctx.textAlign = "center";
ctx.fillStyle = C.ink;
ctx.fillText("half V squared = g h", pv2, pivy + Lr + 48);
ctx.fillStyle = C.faint;
ctx.fillText("V from stage 1 is the only link", pv2, pivy + Lr + 66);
